import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Detect input format
    if not adj:
        return []
    n = len(adj)
    if len(adj[0]) == n and all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        # Adjacency list
        neighbors = [list(set(lst)) for lst in adj]  # ensure no duplicates
        # Ensure symmetry if not already (undirected graph assumption)
        for i in range(n):
            for j in neighbors[i]:
                if i not in neighbors[j]:
                    neighbors[j].append(i)

    if n == 0:
        return []
    if n == 1:
        return [0]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: compute saturation degree for DSATUR
    def saturation_degree(v, color):
        used = set()
        for u in neighbors[v]:
            if color[u] != -1:
                used.add(color[u])
        return len(used)

    # DSATUR implementation
    def dsatur():
        color = [-1] * n
        # Order vertices by degree descending for initial tie-breaking in degree
        order = list(range(n))
        order.sort(key=lambda x: (-len(neighbors[x]), x))
        for _ in range(n):
            # Select uncolored vertex with max saturation degree, tie-break by degree in uncolored subgraph, then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if color[u] == -1:
                    sat = saturation_degree(u, color)
                    deg = sum(1 for w in neighbors[u] if color[w] == -1)
                    if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and u < v):
                        max_sat = sat
                        max_deg = deg
                        v = u
            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # RLF implementation (Largest First Independent Set)
    def rlf():
        color = [-1] * n
        remaining = set(range(n))
        c = 0
        while remaining:
            # Build maximal independent set for color c
            # Start with vertex of max degree in remaining subgraph
            v = max(remaining, key=lambda x: sum(1 for y in neighbors[x] if y in remaining))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set (eligible)
            # W: vertices adjacent to at least one in independent_set (ineligible)
            U = {u for u in remaining if u != v and all(u not in neighbors[w] for w in independent_set)}
            W = {u for u in remaining if u != v and any(u in neighbors[w] for w in independent_set)}
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: sum(1 for y in neighbors[x] if y in W))
                # Tie-break: min degree in G[U]
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in independent_set
            for v in independent_set:
                color[v] = c
            remaining -= independent_set
            c += 1
        return color

    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [len(neighbors[i]) for i in range(n)]
        # We'll simulate peeling
        temp_adj = [set(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # Find vertex of min degree in remaining
            v = min(remaining, key=lambda x: len(temp_adj[x] & remaining))
            order.append(v)
            remaining.remove(v)
            # Remove v from neighbors' temp_adj
            for u in temp_adj[v]:
                if u in remaining:
                    temp_adj[u].discard(v)
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Welsh-Powell ordering
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), x))
        return greedy_color(order)

    # Kempe chain refinement to reduce colors
    def kempe_refine(color):
        # Determine current number of colors
        max_color = max(color) if color else -1
        if max_color < 0:
            return color
        # Try to eliminate color classes from highest down
        for target_color in range(max_color, 0, -1):
            # Get vertices with target_color
            verts = [v for v in range(n) if color[v] == target_color]
            if not verts:
                continue
            # Try to recolor each vertex in this class
            changed = True
            while changed and verts:
                changed = False
                new_verts = []
                for v in verts:
                    if color[v] != target_color:  # might have been recolored already
                        continue
                    # Try to move v to a lower color directly
                    neighbor_colors = set(color[u] for u in neighbors[v])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            color[v] = c
                            changed = True
                            break
                    if color[v] == target_color:
                        new_verts.append(v)
                verts = new_verts
            if not verts:  # entire class eliminated
                # Reindex colors above target_color down by one
                for v in range(n):
                    if color[v] > target_color:
                        color[v] -= 1
                break  # restart from new max color
            else:
                # Try Kempe chains for remaining verts in this class
                for v in verts:
                    if color[v] != target_color:
                        continue
                    neighbor_colors = set(color[u] for u in neighbors[v])
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # Check if v is connected to any vertex of color c via a Kempe chain (c, target_color)
                        # We'll do BFS from v in the subgraph of colors c and target_color
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        chain_has_c = False
                        while queue:
                            x = queue.popleft()
                            if color[x] == c:
                                chain_has_c = True
                            for y in neighbors[x]:
                                if color[y] in (c, target_color) and y not in visited:
                                    visited.add(y)
                                    queue.append(y)
                        # If the chain does NOT contain color c, we can swap
                        if not chain_has_c:
                            # Swap colors c and target_color in the component
                            for x in visited:
                                if color[x] == c:
                                    color[x] = target_color
                                elif color[x] == target_color:
                                    color[x] = c
                            color[v] = c  # now v is color c
                            changed = True
                            break
                    if color[v] != target_color:
                        break
                if changed:
                    # Restart the target_color loop since colors shifted
                    break
        return color

    # Generate candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())
    candidates.append(welsh_powell())

    # Also try greedy with random orders (limited)
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        candidates.append(greedy_color(order))

    # Refine each candidate with Kempe chains
    refined = []
    for col in candidates:
        refined.append(kempe_refine(col[:]))

    # Select the candidate with the fewest colors
    best = min(refined, key=lambda c: max(c) + 1 if c else 0)
    return best

