import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and adjacency sets
    if is_matrix:
        neighbors = []
        for i in range(n):
            nbrs = [j for j in range(n) if adj[i][j] == 1]
            neighbors.append(nbrs)
    else:
        neighbors = adj

    # Ensure undirected and remove duplicates
    for u in range(n):
        for v in neighbors[u]:
            if u not in neighbors[v]:
                neighbors[v].append(u)
    for i in range(n):
        neighbors[i] = sorted(set(neighbors[i]))

    # Trivial cases
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n
    if all(len(neighbors[i]) == n - 1 for i in range(n)):
        return list(range(n))

    # Precompute degrees and adjacency sets
    degree = [len(neighbors[i]) for i in range(n)]
    adj_set = [set(neighbors[i]) for i in range(n)]

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: check validity of coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compute lower bound via maximum clique approximation (greedy)
    def clique_lower_bound():
        remaining = set(range(n))
        clique_size = 0
        while remaining:
            v = max(remaining, key=lambda x: len(adj_set[x] & remaining))
            clique_size += 1
            remaining = adj_set[v] & remaining
        return clique_size

    # Strategy 1: DSATUR with bitmask optimization (for speed)
    def dsatur():
        color = [-1] * n
        saturation = [0] * n  # bitmask: bit i set if color i used by neighbor
        uncolored = set(range(n))
        while uncolored:
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = bin(saturation[v]).count("1")
                deg_in_uncolored = len(adj_set[v] & uncolored)
                if sat_v > best_sat or (sat_v == best_sat and deg_in_uncolored > best_deg) or \
                   (sat_v == best_sat and deg_in_uncolored == best_deg and v > best_v):
                    best_sat = sat_v
                    best_deg = deg_in_uncolored
                    best_v = v
            v = best_v
            c = 0
            while saturation[v] & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_set[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
        return color

    # Strategy 2: RLF with efficient set operations
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            v = max(uncolored, key=lambda x: len(adj_set[x] & uncolored))
            independent_set = {v}
            to_remove = {v}
            U = {u for u in uncolored if u != v and adj_set[u].isdisjoint(independent_set)}
            W = uncolored - independent_set - U
            while U:
                best_u = -1
                best_score = -1
                best_deg_U = float('inf')
                for u in U:
                    score = len(adj_set[u] & W)
                    deg_U = len(adj_set[u] & U)
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or \
                       (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u_star = best_u
                independent_set.add(u_star)
                to_remove.add(u_star)
                U.remove(u_star)
                for w in adj_set[u_star]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            for vtx in independent_set:
                color[vtx] = c
            uncolored -= to_remove
            c += 1
        return color

    # Strategy 3: Smallest-Last (Matula & Beck) with bucket sort
    def smallest_last():
        remaining = set(range(n))
        deg = degree[:]
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            if deg[v] <= max_deg:
                buckets[deg[v]].append(v)
        order = []
        ptr = 0
        while remaining:
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            remaining.remove(v)
            order.append(v)
            for u in neighbors[v]:
                if u in remaining:
                    old_deg = deg[u]
                    if old_deg <= max_deg and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
                    deg[u] -= 1
                    new_deg = deg[u]
                    if new_deg <= max_deg:
                        buckets[new_deg].append(u)
                    else:
                        while len(buckets) <= new_deg:
                            buckets.append([])
                        buckets[new_deg].append(u)
            while ptr > 0 and not buckets[ptr]:
                ptr -= 1
        return greedy_color(order[::-1])

    # Strategy 4: Welsh-Powell
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        return greedy_color(order)

    # Strategy 5: Randomized greedy with restarts
    def randomized_greedy(iterations=30):
        best_coloring = None
        best_num = float('inf')
        max_iter = min(iterations, n * n + 1)
        for _ in range(max_iter):
            order = list(range(n))
            random.shuffle(order)
            coloring = greedy_color(order)
            if is_valid(coloring):
                num = num_colors(coloring)
                if num < best_num:
                    best_num = num
                    best_coloring = coloring[:]
                    if best_num == 1:
                        break
        return best_coloring if best_coloring is not None else greedy_color(list(range(n)))

    # Kempe chain reduction to improve coloring (optimized)
    def kempe_reduce(coloring):
        color = coloring[:]
        k = num_colors(color)
        if k <= 1:
            return color
        # Build color classes
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            color_classes[color[v]].append(v)
        changed = True
        while changed and k > 1:
            changed = False
            target_color = k - 1
            if not color_classes[target_color]:
                k -= 1
                color_classes.pop()
                continue
            # Try to recolor vertices in target_color
            for v in color_classes[target_color][:]:
                moved = False
                # Try direct recoloring to a lower color
                for c in range(target_color):
                    conflict = False
                    for u in adj_set[v]:
                        if color[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        color[v] = c
                        color_classes[c].append(v)
                        color_classes[target_color].remove(v)
                        moved = True
                        changed = True
                        break
                if moved:
                    continue
                # Try Kempe chain swap
                for c in range(target_color):
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    has_color_c = False
                    while stack:
                        x = stack.pop()
                        if color[x] == c:
                            has_color_c = True
                        for y in adj_set[x]:
                            if y not in visited and (color[y] == target_color or color[y] == c):
                                visited.add(y)
                                stack.append(y)
                    if not has_color_c:
                        # Swap colors in the component
                        for x in visited:
                            if color[x] == target_color:
                                color[x] = c
                                color_classes[c].append(x)
                                color_classes[target_color].remove(x)
                            elif color[x] == c:
                                color[x] = target_color
                                color_classes[target_color].append(x)
                                color_classes[c].remove(x)
                        moved = True
                        changed = True
                        break
                if moved:
                    break
        # Reindex colors to be contiguous
        k = 0
        new_color_classes = []
        for c_list in color_classes:
            if c_list:
                new_color_classes.append(c_list)
                k += 1
        color_map = {}
        new_color = [-1] * n
        for idx, c_list in enumerate(new_color_classes):
            for v in c_list:
                color_map[v] = idx
                new_color[v] = idx
        return new_color

    # Run strategies and select best
    strategies = [dsatur, rlf, smallest_last, welsh_powell, randomized_greedy]
    best_coloring = None
    best_num_colors = float('inf')

    for strategy in strategies:
        try:
            coloring = strategy()
            if is_valid(coloring):
                reduced = kempe_reduce(coloring)
                if is_valid(reduced):
                    num = num_colors(reduced)
                    if num < best_num_colors:
                        best_num_colors = num
                        best_coloring = reduced[:]
                        # Early exit if we hit the lower bound (clique number)
                        lb = clique_lower_bound()
                        if best_num_colors == lb:
                            break
                else:
                    # Fallback if reduction broke validity (should not happen)
                    if num < best_num_colors:
                        best_num_colors = num
                        best_coloring = coloring[:]
        except Exception:
            continue

    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))

    return best_coloring
